function OverseaClubBossRankDialog:InitToggleData()
    self.togglesData = {}
    local config = self:GetConfig()
    for i, v in pairs(config) do
        table.insert(self.togglesData, {
            text = v.text,
            func = Bind(self, self.TopTabOnClickHandler),
