function OverseaClubBossRankDialog:TopTabOnClickHandler(index)
    local data = self.togglesData[index]
    if self.isPlay then
        CfUtils.PlayAnimation(self.Container.gameObject,"OverseaClubBossRankDialog_Switch",true)
    else
        self.isPlay = true
    end
    if not isNull(data) then
        self.data = data
        local type = data.type
        self.type = type
        KTool.SetActive(self.ClubRank.gameObject,type == ClubUtils.BossRankType.AllServerClub)
        KTool.SetActive(self.MemberRank.gameObject,type ~= ClubUtils.BossRankType.AllServerClub)
        GameUtils.Request(data.interface,{},function(request,response)
            if response.errCode == 0 then
                local serverData = response.data
                if type == ClubUtils.BossRankType.AllServerClub then
                    self.clubRankEnv:SetIsCurrent(true)
                    self.clubRankEnv:RefreshShow(type,serverData)
                    self.clubRankEnv:ShowBtnLast(not data.hideLastBtn)
                else
                    self.memberRankEnv:SetIsCurrent(true)
                    self.memberRankEnv:RefreshShow(type,serverData)
                    self.memberRankEnv:ShowBtnLast(not data.hideLastBtn)
                end
                KTool.SetActive(self.EmptyNode.gameObject,table.count(serverData.rankInfo) <= 0)
                KTool.SetActive(self.Root.gameObject,true)
            end
        end)
    end
end

function OverseaClubBossRankDialog:OnSeeLastScheduleClick(current)
    local current = current and 0 or 1
    GameUtils.Request(self.data.interface,{isLastSchedule = current},function(request,response)
        if response.errCode == 0 then
            local serverData = response.data
            if self.type == ClubUtils.BossRankType.AllServerClub then
                self.clubRankEnv:RefreshShow(self.type,serverData)
            else
                self.memberRankEnv:RefreshShow(self.type,serverData)
            end
            KTool.SetActive(self.EmptyNode.gameObject,table.count(serverData.rankInfo) <= 0)
        end
    end)
end

return OverseaClubBossRankDialog